// O endpoint devolve o efetivo ocupado do momento, sem data no caminho.
// Esta data so CARIMBA o registro (data_consulta) quando a resposta nao traz a dela.
// Vazio = data vigente no fuso de Sao Paulo.
const DATA_MANUAL = '';
const data = DATA_MANUAL || $now.setZone('America/Sao_Paulo').toFormat('yyyy-MM-dd');
if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) throw new Error('DATA_MANUAL deve estar no formato YYYY-MM-DD');
return [{ json: { data } }];

const data = $('Definir data de referência').first().json.data;
const ids = [32, 51, 66, 73, 86, 87, 88, 89, 90, 94, 110, 114, 115, 121, 127];
return ids.map(id_eap => ({ json: { id_eap, data } }));

const corpo = $json.data ?? $json.body?.data ?? $json.body ?? $json;
const idEap = $('Loop id_eap (1 por vez)').item.json.id_eap;

const vazio = v => v === null || v === undefined || (typeof v === 'string' && v.trim() === '');
const n = v => { if (vazio(v)) return null; const x = Number(typeof v === 'string' ? v.trim().replace(',', '.') : v); return Number.isFinite(x) ? x : null; };
const s = (v, max) => { if (vazio(v) || typeof v === 'object') return null; const t = String(v).trim(); return t.length > max ? t.slice(0, max) : t; };
const d = v => { if (vazio(v)) return null; const t = String(v).trim().slice(0, 10); return /^\d{4}-\d{2}-\d{2}$/.test(t) ? t : null; };
const q = String.fromCharCode(96);
const escapar = (v) => "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\x00/g, '') + "'";
const sqlVal = (v) => (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? String(v) : escapar(v));

// A API carimba a propria data da consulta; a data do fluxo e so rede de seguranca.
const dataRef = d(corpo.data_cadastro ?? corpo.data_consulta) ?? d($('Loop id_eap (1 por vez)').item.json.data);
if (!dataRef) throw new Error('Sem data de consulta valida para id_eap ' + idEap);

const listaTarefas = corpo.tarefas ?? corpo.efetivo ?? (Array.isArray(corpo) ? corpo : null);
if (!Array.isArray(listaTarefas)) throw new Error('Formato inesperado em efetivo_ocupado/' + idEap + ' - chaves recebidas: ' + JSON.stringify(Object.keys(corpo || {})));

// A resposta vem por TAREFA, com a lista de pessoas dentro de funcionarios_alocados.
// Vira uma linha por (tarefa x funcionario). Tarefa sem ninguem alocado nao gera linha.
// Nao dava para fazer merge tarefa+funcionario: os dois objetos tem a chave "id".
const rows = [];
let vistos = 0;
let comChaveRuim = 0;
let amostraRuim = null;

// limites de texto = tamanho das colunas em painelmse.eap_apontamento_efetivo
for (const t of listaTarefas) {
  const alocados = t.funcionarios_alocados ?? t.funcionarios ?? t.alocacoes ?? [];
  if (!Array.isArray(alocados) || alocados.length === 0) continue;
  const tarefaId = n(t.id ?? t.tarefa_id ?? t.id_tarefa);
  for (const f of alocados) {
    vistos++;
    const funcionarioId = n(f.id ?? f.funcionario_id ?? f.id_funcionario);
    if (tarefaId == null || funcionarioId == null) {
      comChaveRuim++;
      if (!amostraRuim) amostraRuim = JSON.stringify({ tarefa: t.id, funcionario: f }).slice(0, 400);
      continue;
    }
    rows.push({
      data_consulta: dataRef,
      tarefa_id: tarefaId,
      funcionario_id: funcionarioId,
      id_eap: n(corpo.id_eap ?? idEap),
      nome_eap: s(corpo.nome_eap, 120),
      id_obra: n(corpo.id_obra),
      nome_obra: s(corpo.nome_obra, 120),
      edt: s(t.edt, 60),
      tarefa_nome: s(t.tarefa ?? t.tarefa_nome, 255),
      funcionario_nome: s(f.nome ?? f.funcionario_nome, 120),
      nome_funcao: s(f.nome_funcao ?? f.funcao, 80),
      empresa: s(f.empresa_contratante ?? f.empresa ?? f.razao_social, 120),
      tabela_origem: s(f.tabela ?? f.tabela_origem, 40)
    });
  }
}

// Sem isto, mapeamento errado vira carga vazia SEM erro: as linhas sao descartadas
// em silencio, o INSERT vira 'SELECT 1' e o fluxo termina verde.
if (vistos > 0 && rows.length === 0) {
  throw new Error('efetivo_ocupado/' + idEap + ': ' + vistos + ' funcionario(s) alocado(s) e NENHUM com id utilizavel. Amostra: ' + amostraRuim);
}

const diagnostico = {
  id_eap: idEap,
  data_consulta: dataRef,
  tarefas_recebidas: listaTarefas.length,
  funcionarios_alocados: vistos,
  descartados: comChaveRuim,
  linhas_validas: rows.length
};

// --- MySQL: painelmse.eap_apontamento_efetivo (PK = data_consulta + tarefa_id + funcionario_id) ---
const COLUNAS = ['data_consulta','tarefa_id','funcionario_id','id_eap','nome_eap','id_obra','nome_obra','edt','tarefa_nome','funcionario_nome','nome_funcao','empresa','tabela_origem'];
const CHAVE = ['data_consulta','tarefa_id','funcionario_id'];
const colsSql = COLUNAS.map(c => q + c + q).join(',');
const tuplas = rows.map(l => '(' + COLUNAS.map(c => sqlVal(l[c])).join(',') + ')').join(',\n');
const updSql = COLUNAS.filter(c => !CHAVE.includes(c)).map(c => q + c + q + ' = VALUES(' + q + c + q + ')').join(', ');
const sqlMySql = rows.length ? 'INSERT INTO eap_apontamento_efetivo (' + colsSql + ') VALUES ' + tuplas + ' ON DUPLICATE KEY UPDATE ' + updSql : 'SELECT 1';

// quem saiu da alocacao no meio do dia tem que sair da tabela (do dia + EAP em questao)
const filtro = 'id_eap = ' + sqlVal(n(idEap)) + ' AND data_consulta = ' + sqlVal(dataRef);
const pares = rows.map(r => '(' + r.tarefa_id + ',' + r.funcionario_id + ')').join(',');
const sqlDelete = rows.length
  ? 'DELETE FROM eap_apontamento_efetivo WHERE ' + filtro + ' AND (tarefa_id, funcionario_id) NOT IN (' + pares + ')'
  : 'DELETE FROM eap_apontamento_efetivo WHERE ' + filtro;

return [{ json: { rows, sqlMySql, sqlDelete, total: rows.length, diagnostico } }];
